hypothesis: >-
  E2 microbenchmarks show the one-SM tc_small at B=192-256 is not limited by the UMMA shape (resident 128x192 reaches
  98.8% of 4096 FLOP/clk when a commit covers at least 8 UMMAs), by the TMA feed (a no-MMA ring costs the same as an
  MMA-only ring), by ring depth beyond 3 stages, or by emb L2 hot-spotting (1 to 36 private copies: within 1%). It is
  limited by a fixed per-stage MMA to commit to mbarrier chain of about 250-300 clk, paid once per 1-k-block stage and
  amortised by larger stages. A cta_group::2 pair halves the emb bytes per CTA, so 2-k-block stages fit, and the same
  work at B=131-256 runs at about the DRAM stream rate (749 vs 1108 clk per k-block, 42.5 vs 60 us wall, probe).
  Clock-bound at the portal lock, so the portal gain should exceed the rented -4..-7%.
expected_effect:
  S:
    pct: 0
    confidence: high
  M:
    pct: -8
    confidence: low
  L:
    pct: 0
    confidence: high
resources_sm100a:
  regs_per_thread: 64
  smem_per_cta_bytes: 230400
  threads_per_cta: 128
  ctas_per_sm: 1
  bytes_in_flight_per_sm: 172032
  launches_per_call: 1
knobs:
  KBS: 2
  STAGES_RULE: "(225 KB - 1 KB) / (2 * (16 KB + Bpad/2 * 128 B)): B=192 -> 4, B=211 (Bpad 224) -> 3, B=256 -> 3"
  W_HINT: evict_first
  TMA_DTYPE: TFLOAT32
  CLUSTER: 2
  PAIR_B_THRESHOLD: "131 < B <= 256"
dispatch:
  - max_tokens: 131
    kernel: tc_small_kernel (unchanged r2 path)
    meta:
      launches: 1
  - max_tokens: 256
    kernel: tc_pair_kernel
    meta:
      launches: 1
  - max_tokens: 384
    kernel: Tf32Gemm<256,192,0>
    meta:
      launches: 1
  - max_tokens: 512
